import{c as e,Q as s,j as r,m as o}from"./chunks/framework.BqPkuuVc.js";const n="/assets/results.CsXzi-sq.png",a="/assets/results-publish-menu.CLV09Rx-.png",i="/assets/event-not-finalised-publish.DKHNdaj4.png",l="/assets/results-print-relay.b60iIaSM.png",v=JSON.parse('{"title":"Results","description":"","frontmatter":{},"headers":[],"relativePath":"user/after-the-event/results.md","filePath":"user/after-the-event/results.md"}'),h={name:"user/after-the-event/results.md"};function d(u,t,g,c,p,f){return s(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and timing operators checking, sharing and publishing results, during the event and after it.</p><p>How to read the <strong>Results</strong> screen, get results to spectators while the event runs, settle and publish the final results, and produce prize-giving lists.</p><h2 id="the-results-screen" tabindex="-1">The Results screen <a class="header-anchor" href="#the-results-screen" aria-label="Permalink to &quot;The Results screen&quot;">​</a></h2><p>Open the event and choose <strong>Results</strong> in the side menu. It lists each class with its competitors in place order, and updates by itself as cards are downloaded and radio punches arrive, so you can leave it open.</p><p><img src="'+n+'" alt="The Results screen: results by class, with Place, Name, Club and Time for each competitor, and the Filters, Display and Include options on the right"></p><p>Each class shows:</p><table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Place</strong></td><td>The finishing place. Only competitors with an <strong>OK</strong> result have one.</td></tr><tr><td><strong>Name</strong>, <strong>Club</strong></td><td>The competitor and their club. <strong>Club</strong> is left out when you are looking at one club&#39;s results.</td></tr><tr><td><strong>Behind</strong></td><td>How far behind the winner, when <strong>Show behind time</strong> is ticked. On a score course it&#39;s how many points behind.</td></tr><tr><td><strong>Points</strong>, <strong>Penalty</strong></td><td>On a score course only: the points collected, and what the time limit took off, if anyone lost any.</td></tr><tr><td><strong>Leg time</strong></td><td>In a relay class: each runner&#39;s own time on their leg (see <a href="#relays">Relays</a>).</td></tr><tr><td><strong>Time</strong></td><td>The race time, including any adjustment you made. For anyone without an OK result it shows their status instead: <strong>MP</strong>, <strong>DNF</strong>, <strong>DSQ</strong> and so on.</td></tr></tbody></table><p>Finishers come first, in place order; competitors with any other result follow them, greyed out. How ties and the order of non-finishers are decided is in <a href="./../reference/status-and-race-time#how-results-are-ordered">How results are ordered</a>.</p><p>Below the classes, <strong>Summary</strong> gives a line per class: how many entries, the winning time, and how many have each status. Its <strong>On course</strong> column is the quickest way to see which classes are still incomplete.</p><h3 id="choosing-what-s-shown" tabindex="-1">Choosing what&#39;s shown <a class="header-anchor" href="#choosing-what-s-shown" aria-label="Permalink to &quot;Choosing what&#39;s shown&quot;">​</a></h3><p>The panel on the right changes what&#39;s on the screen, and what <strong>Print view</strong> and <strong>Export PDF</strong> produce from it. It is reset when you leave the screen.</p><p><strong>Filters</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Group by</strong></td><td><strong>Class</strong> (the default) or <strong>Course</strong>. By course puts everyone who ran the same course into one list, whatever their class.</td></tr><tr><td><strong>Classes</strong> / <strong>Courses</strong></td><td>Only these classes or courses. Leave it empty for all of them.</td></tr><tr><td><strong>Organisation</strong></td><td>Only competitors from these clubs: results for one club&#39;s newsletter, say. The heading becomes &quot;Results for <em>club</em>&quot;.</td></tr><tr><td><strong>Show</strong></td><td><strong>All</strong>, or only the <strong>Top 3</strong> to <strong>Top 10</strong> of each class.</td></tr></tbody></table><p><strong>Display</strong></p><ul><li><strong>Show behind time</strong> — adds the <strong>Behind</strong> column. Off to begin with.</li><li><strong>Show summary</strong> — the summary table at the bottom. On to begin with.</li></ul><p><strong>Include</strong></p><p>These add competitors who are normally left out of the lists. All four are off to begin with:</p><ul><li><strong>Provisional results</strong> — competitors who crossed a radio finish but whose card hasn&#39;t been downloaded. They have a time and a place, marked with <code>*</code>, and may still change: the card might show a missed control. See <a href="./../reference/status-and-race-time#provisional-vs-final-ok">Provisional vs final OK</a>.</li><li><strong>On course competitors</strong> — those still out, for a picture of the class with the field not yet home.</li><li><strong>Status none competitors</strong> — those nobody has accounted for yet.</li><li><strong>Did not start</strong> — those marked <strong>DNS</strong>.</li></ul><blockquote><p><strong>Note:</strong> <strong>Include</strong> only changes what you see here. An exported results file, or an upload to Eventor, always accounts for everyone in the classes you choose, whatever is ticked. See <a href="./../reference/status-and-race-time#what-an-exported-results-file-contains">What an exported results file contains</a>.</p></blockquote><h3 id="relays" tabindex="-1">Relays <a class="header-anchor" href="#relays" aria-label="Permalink to &quot;Relays&quot;">​</a></h3><p>A relay class lists each <strong>team</strong> with its place and total time, and the team&#39;s runners underneath in leg order. For each runner, <strong>Leg time</strong> is their own time on their leg, with a status beside it if their leg went wrong, and <strong>Time</strong> is the team&#39;s running total at their changeover. On the last leg, that is the team&#39;s result. See <a href="./../event-setup/relay-events">Relay events</a>.</p><h2 id="results-while-the-event-is-running" tabindex="-1">Results while the event is running <a class="header-anchor" href="#results-while-the-event-is-running" aria-label="Permalink to &quot;Results while the event is running&quot;">​</a></h2><p>The Results screen is for you. Spectators, competitors and the people at home see results elsewhere, and each of these updates on its own as the race goes on:</p><table tabindex="0"><thead><tr><th>Where</th><th>Who sees it</th><th>Set up on</th></tr></thead><tbody><tr><td><strong>TV screens</strong> at the arena</td><td>Everyone at the event</td><td><a href="./../screens/tv-screens">TV screens</a></td></tr><tr><td>The <strong>spectator site</strong> and the <strong>kiosk</strong>, on phones and a tablet at the arena</td><td>Anyone on the event&#39;s network</td><td><a href="./../screens/spectator-site-and-kiosk">Spectator site and kiosk</a></td></tr><tr><td><strong>Commentary</strong></td><td>The commentator</td><td><a href="./../screens/commentary">Commentary</a></td></tr><tr><td><strong>liveresultat.orientering.se</strong></td><td>Anyone on the internet</td><td><strong>Event details → Live results</strong> (see <a href="./../running-the-event/publishing-live-results">Publishing live results online</a>)</td></tr><tr><td>The <strong>meshO cloud</strong></td><td>Anyone on the internet, once the event is published there</td><td><strong>Settings → Cloud sync</strong>, and <strong>Event details → Cloud sync</strong> for each event (see <a href="./../running-the-event/publishing-live-results#publishing-to-the-mesho-cloud">Publishing live results online</a>)</td></tr><tr><td>A <strong>live export</strong> file, rewritten every few minutes, for another results system to read</td><td>That system</td><td><strong>Event details → Backup &amp; export → Live export</strong> (see <a href="./../event-setup/create-event#live-export">Creating an event</a>)</td></tr></tbody></table><p>Each of these shows the race as it happens. Runners still on course appear as on course, and a radio finish appears with its time before the card is read. That&#39;s the point of a live feed, and it is different from the final results file below.</p><p>Two things hold results back on purpose:</p><ul><li><strong>Results quarantine.</strong> An elite class can have its results held back from every public screen until a set time or the last start, while its start list stays visible. You still see everything here. See <a href="./../event-setup/results-quarantine">Results quarantine</a>.</li><li><strong>liveresultat only publishes while the event is live.</strong> Nothing is sent before <strong>Start event</strong>, or after the event is finished.</li></ul><h2 id="publishing-the-final-results" tabindex="-1">Publishing the final results <a class="header-anchor" href="#publishing-the-final-results" aria-label="Permalink to &quot;Publishing the final results&quot;">​</a></h2><p>When the last runner is home and every result is settled, publish from <strong>Publish</strong> at the top of the Results screen:</p><p><img src="'+a+'" alt="The Publish menu open on the Results screen: Export IOF XML, Export JSON, Export PDF, Print view and Print to splits printer"></p><table tabindex="0"><thead><tr><th>Item</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Export IOF XML…</strong></td><td>The standard results file for other systems, and for uploading to Eventor by hand.</td></tr><tr><td><strong>Export JSON…</strong></td><td>The same results in <a href="./../advanced/orienteering-json">Orienteering JSON</a>.</td></tr><tr><td><strong>Export PDF…</strong></td><td>A results document to share or archive.</td></tr><tr><td><strong>Upload to Eventor…</strong></td><td>Sends the results straight to the event on Eventor. Only offered when Eventor is set up in <strong>Settings → Eventor</strong>.</td></tr><tr><td><strong>Print view…</strong></td><td>Opens the browser&#39;s print dialog with a printable page of the results.</td></tr><tr><td><strong>Print to splits printer…</strong></td><td>Prints a results sheet on a thermal printer (see <a href="#prize-giving-and-the-results-board">Prize-giving and the results board</a>).</td></tr></tbody></table><p>Each opens <strong>Publish options</strong> first. For the PDF and the print view you choose the classes, the grouping, the clubs, top places only or everyone, and whether to show the behind time and the summary. For a file or an upload you choose the classes and whether competitors marked <strong>DNS</strong> go in (<strong>Include DNS competitors</strong>). If anyone in the file was timed from a check punch or from midnight rather than a recorded start, the dialog says how many: their times and places go out as they are, so check them first if that matters. The options for a file, such as one country&#39;s results or combined classes for the World Ranking, are covered in <a href="./exports">Exporting data</a>.</p><h3 id="settling-everyone-first" tabindex="-1">Settling everyone first <a class="header-anchor" href="#settling-everyone-first" aria-label="Permalink to &quot;Settling everyone first&quot;">​</a></h3><p>A results file says what became of <strong>everyone</strong> who took part, so Manager checks first. If anybody in the classes you chose still has no status, is still on course, or has only a radio finish, you see <strong>Event not finalised</strong> instead of the options:</p><p><img src="'+i+'" alt="Event not finalised: counts of competitors with no status, on course, with a radio finish only, and a radio finish nobody is entered on, with buttons to settle each"></p><p>Its buttons settle each group: <strong>Set competitors DNS…</strong> for those who never started, <strong>Set competitors overtime…</strong> for those still out, and <strong>Set radio finishes DNF or overtime…</strong> for finishes whose card was never read. <strong>Show pending…</strong> covers a card that finished but belongs to nobody. Once everyone is settled, Manager carries on to the publish options.</p><p><strong>Ignore and continue</strong> publishes anyway. Those with no status go in as <strong>DNS</strong>, and those still out or with only a radio finish as <strong>DNF</strong>. Settling them properly is better: a DNF in a published results file is a statement about a runner. The full rules, and how this works at a multi-day event, are in <a href="./../reference/status-and-race-time#what-an-exported-results-file-contains">What an exported results file contains</a>.</p><p><strong>Finish event</strong> runs the same check. There the button reads <strong>Finish anyway</strong>, and it isn&#39;t offered while a radio finish is still waiting for its card (or a card that finished belongs to nobody): download the card, or settle it with the buttons, first. So the usual order at the end of the day is:</p><ol><li>Download the last cards and settle anyone left over (the dashboard&#39;s <strong>On course</strong> and <strong>Pending</strong> counts show who).</li><li>Click <strong>Finish event</strong>.</li><li>Publish: upload to Eventor, export the file your federation wants, print or export the PDF.</li></ol><p>There is no separate &quot;mark as official&quot; step. A result is final once the card is read, and the file is complete once everyone is settled. If cloud sync is on, finishing the event also publishes it to the cloud (see <a href="./../running-the-event/publishing-live-results#publishing-to-the-mesho-cloud">Publishing to the meshO cloud</a>).</p><h3 id="when-a-result-is-disputed" tabindex="-1">When a result is disputed <a class="header-anchor" href="#when-a-result-is-disputed" aria-label="Permalink to &quot;When a result is disputed&quot;">​</a></h3><p>A protest or a mistake found later is fixed on the competitor, not on the Results screen. Open the competitor (<strong>Edit competitor</strong>):</p><ul><li><strong>To disqualify, or to record DNF or Overtime</strong>, change the <strong>Status</strong> on the <strong>Result</strong> tab.</li><li><strong>To give a control a runner did visit</strong>, override the punch on the <strong>Overrides</strong> tab. You can&#39;t set <strong>OK</strong> directly while the card shows a missed control: Manager checks OK against the punches, so a corrected punch is what turns an <strong>MP</strong> into an <strong>OK</strong>.</li><li><strong>To correct a start or finish time</strong>, use the <strong>Overrides</strong> tab as well.</li></ul><p>The Results screen, the public screens and the live feeds update straight away. A file you have already exported or uploaded does not: export or upload it again. The competitor&#39;s <strong>Audit trail</strong> tab records what was changed and when (see <a href="./../reference/audit-trail">Audit trail</a>). For more recipes, see <a href="./../running-the-event/resolving-issues#competitor-results">Resolving issues on the day</a>.</p><h2 id="prize-giving-and-the-results-board" tabindex="-1">Prize-giving and the results board <a class="header-anchor" href="#prize-giving-and-the-results-board" aria-label="Permalink to &quot;Prize-giving and the results board&quot;">​</a></h2><p>For the presentation, set <strong>Show</strong> to <strong>Top 3</strong> (or however many places you award), choose the classes, then use <strong>Print view</strong> or <strong>Export PDF</strong>. A results list cut to the places being presented makes a straightforward script for whoever reads them out.</p><p>To pin results up at the arena as they come in, use <strong>Print to splits printer…</strong>. It prints a results sheet on a printer, with its own choice of classes, top places and columns, and a preview of the sheet before you print. It opens on the printer this computer&#39;s splits go to, and you can choose any other printer this computer can use (see <a href="./../running-the-event/splits-printing">Printing splits</a>):</p><p><img src="'+l+'" alt="Print results on the splits printer: Show Top 3, classes, organisation and Include options on the left, the printer, and a preview of the roll showing a relay class&#39;s top three teams with their runners"></p><ul><li><strong>Unsettled classes</strong> includes classes where somebody still out could yet take a place; they are marked with an asterisk. Leave it off to print only classes whose places can&#39;t change: those are safe to present.</li><li><strong>On course</strong>, <strong>No status</strong> and <strong>DNS</strong> add those competitors to the sheet as well as the finishers.</li><li><strong>Club</strong> and <strong>Behind</strong> give each its own column. A narrow roll drops them so the names stay readable.</li><li><strong>Team members</strong> lists a relay team&#39;s runners under it, each with their own leg time.</li></ul><h2 id="overall-results-for-a-multi-stage-event" tabindex="-1">Overall results for a multi-stage event <a class="header-anchor" href="#overall-results-for-a-multi-stage-event" aria-label="Permalink to &quot;Overall results for a multi-stage event&quot;">​</a></h2><p>A stage of a <a href="./../event-setup/multi-stage-events">multi-stage event</a> has its own results, read here exactly like any other event&#39;s. The <strong>combined</strong> result across the stages lives on the carnival&#39;s <strong>Standings</strong> tab, not here: open the group header on the Events page.</p><p>The standings show, per class, each competitor&#39;s position, their contribution from each stage, and their total. They update live as a stage runs, so the overall is correct within about half a second of a card being downloaded. A stage that didn&#39;t count is struck through with the reason, and a total that is still provisional carries <code>*</code>.</p><p>See <a href="./../event-setup/multi-stage-events#standings">Standings</a> for what the columns and statuses mean.</p><h2 id="the-overall-result-of-a-knock-out-competition" tabindex="-1">The overall result of a knock-out competition <a class="header-anchor" href="#the-overall-result-of-a-knock-out-competition" aria-label="Permalink to &quot;The overall result of a knock-out competition&quot;">​</a></h2><p>A <a href="./../event-setup/knock-out-competitions">knock-out competition</a> is decided by how far each competitor got, not by a total, so its overall result is a <strong>classification</strong> rather than standings. It lives on the competition&#39;s <strong>Classification</strong> tab.</p><p>It updates by itself as cards are downloaded, so it can stay up on a second screen through the final. <strong>Export CSV</strong> at the top of the tab downloads it: each competitor&#39;s overall place, and the place they took in each round. Each round&#39;s own results read and export here exactly like any other event&#39;s. See <a href="./../event-setup/knock-out-competitions#downloading-it">Knock-out competitions</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./exports">Exporting data</a> — the IOF XML and JSON files, one country&#39;s results, combined classes</li><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — what each status means, and what a results file contains</li><li><a href="./../running-the-event/who-is-still-on-course">Who is still on course</a></li><li><a href="./../running-the-event/resolving-issues">Resolving issues on the day</a></li><li><a href="./../event-setup/results-quarantine">Results quarantine</a></li><li><a href="./../running-the-event/publishing-live-results">Publishing live results online</a> — liveresultat and the meshO cloud</li><li><a href="./end-of-event-checklist">End-of-event checklist</a></li><li><a href="./../screens/leaderboard">Leaderboard</a> — the live results board inside Manager</li></ul>',59)])])}const b=e(h,[["render",d]]);export{v as __pageData,b as default};
